// The reader's own script. Installed by the app as a WKUserScript in an isolated content world, so the
// page (mail content) can neither see `Tern` nor reach the message handler. Mail HTML never runs
// script: the page CSP is `script-src 'none'` and content JavaScript is off.
(() => {
  'use strict';
  const handler = window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.tern;
  const post = (message) => { try { handler.postMessage(message); } catch (_) { /* detached */ } };

  // ICONS:BEGIN generated by scripts/hugeicons.py (Hugeicons Stroke Rounded, MIT)
  const ICON_FILE = '<svg viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"><path d="M 8 17 L 16 17" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M 8 13 L 12 13" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M 13 2.5 L 13 3 C 13 5.828 13 7.243 13.879 8.121 C 14.757 9 16.172 9 19 9 L 19.5 9 M 20 10.657 L 20 14 C 20 17.771 20 19.657 18.828 20.828 C 17.657 22 15.771 22 12 22 C 8.229 22 6.343 22 5.172 20.828 C 4 19.657 4 17.771 4 14 L 4 9.456 C 4 6.211 4 4.588 4.886 3.489 C 5.065 3.267 5.267 3.065 5.489 2.886 C 6.588 2 8.211 2 11.456 2 C 12.161 2 12.514 2 12.837 2.114 C 12.904 2.138 12.97 2.165 13.034 2.196 C 13.344 2.344 13.593 2.593 14.092 3.092 L 18.828 7.828 C 19.407 8.406 19.695 8.696 19.848 9.063 C 20 9.431 20 9.839 20 10.657 Z" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>';
  const ICON_IMAGE = '<svg viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"><path d="M 6 7.5 A 1.5 1.5 0 1 0 9 7.5 A 1.5 1.5 0 1 0 6 7.5 Z" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M 2.5 12 C 2.5 7.522 2.5 5.282 3.891 3.891 C 5.282 2.5 7.522 2.5 12 2.5 C 16.478 2.5 18.718 2.5 20.109 3.891 C 21.5 5.282 21.5 7.522 21.5 12 C 21.5 16.478 21.5 18.718 20.109 20.109 C 18.718 21.5 16.478 21.5 12 21.5 C 7.522 21.5 5.282 21.5 3.891 20.109 C 2.5 18.718 2.5 16.478 2.5 12 Z" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M 5 21 C 9.372 15.775 14.274 8.884 21.497 13.542" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>';
  const ICON_CHEVRON = '<svg viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"><path d="M 18 9 C 18 9 13.581 15 12 15 C 10.419 15 6 9 6 9" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>';
  const ICON_SPARK = '<svg viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"><path d="M 15 2 L 15.539 4.392 C 15.996 6.42 17.58 8.004 19.608 8.461 L 22 9 L 19.608 9.539 C 17.58 9.996 15.996 11.58 15.539 13.608 L 15 16 L 14.461 13.608 C 14.004 11.58 12.42 9.996 10.392 9.539 L 8 9 L 10.392 8.461 C 12.42 8.004 14.004 6.42 14.461 4.392 L 15 2 Z" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M 7 12 L 7.385 13.708 C 7.711 15.157 8.843 16.289 10.292 16.615 L 12 17 L 10.292 17.385 C 8.843 17.711 7.711 18.843 7.385 20.292 L 7 22 L 6.615 20.292 C 6.289 18.843 5.157 17.711 3.708 17.385 L 2 17 L 3.708 16.615 C 5.157 16.289 6.289 15.157 6.615 13.708 L 7 12 Z" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>';
  const ICON_MORE = '<svg viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"><path d="M 6.004 12.5 L 6.004 12 M 18.005 12.5 L 18.005 12 M 12.005 12.5 L 12.005 12 M 7.004 12.5 C 7.004 11.948 6.557 11.5 6.004 11.5 C 5.452 11.5 5.004 11.948 5.004 12.5 C 5.004 13.052 5.452 13.5 6.004 13.5 C 6.557 13.5 7.004 13.052 7.004 12.5 Z M 19.005 12.5 C 19.005 11.948 18.557 11.5 18.005 11.5 C 17.452 11.5 17.005 11.948 17.005 12.5 C 17.005 13.052 17.452 13.5 18.005 13.5 C 18.557 13.5 19.005 13.052 19.005 12.5 Z M 13.005 12.5 C 13.005 11.948 12.557 11.5 12.005 11.5 C 11.452 11.5 11.005 11.948 11.005 12.5 C 11.005 13.052 11.452 13.5 12.005 13.5 C 12.557 13.5 13.005 13.052 13.005 12.5 Z" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>';
  const ICON_PLUS = '<svg viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"><path d="M 12.001 5 L 12.001 19.002" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M 19.002 12.002 L 5 12.002" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>';
  // ICONS:END
  const MIN_SCALE = 0.45;

  let baseSheet = null;
  let state = null;
  let hoverHref = null;
  let fitQueued = false;

  const esc = (value) => String(value == null ? '' : value).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  const root = () => document.getElementById('thread');
  const messageElement = (id) => root().querySelector(`.msg[data-id="${CSS.escape(id)}"]`);

  function sheet() {
    if (!baseSheet) {
      baseSheet = new CSSStyleSheet();
      const source = document.getElementById('mail-base');
      baseSheet.replaceSync(source ? source.textContent : '');
    }
    return baseSheet;
  }

  function afterPaint(callback) {
    if (document.visibilityState === 'hidden') { setTimeout(callback, 0); return; }
    requestAnimationFrame(() => requestAnimationFrame(callback));
  }

  // MARK: Markup

  function headerHTML(p) {
    let html = `<header class="head"><h1 class="subject">${esc(p.subject || '(no subject)')}</h1><div class="chips">`;
    // `icon` is Tern's own SVG from the app (never mail content); everything else is escaped.
    for (const chip of p.chips || []) {
      const style = chip.color ? ` style="--chip:${esc(chip.color)}"` : '';
      html += `<span class="chip ${esc(chip.kind || '')}"${style}>${chip.icon || ''}<span>${esc(chip.text)}</span></span>`;
    }
    html += `<span class="chip-add" data-act="tags" role="button" title="Label or Project" aria-label="Label or Project">${ICON_PLUS}</span>`;
    return html + `</div>${summaryHTML(p.summary)}</header>`;
  }

  function summaryHTML(s) {
    if (!s || s.state === 'none') return '<div class="summary" hidden></div>';
    if (s.state === 'action') {
      return `<div class="summary action" data-act="summary"><span class="spark">${ICON_SPARK}</span><span class="text">${esc(s.label || 'Summarize')}</span></div>`;
    }
    if (s.state === 'loading') {
      const line = s.text ? `<p>${esc(s.text)}</p>` : '<p>Summarizing…</p>';
      return `<div class="summary loading"><span class="spark">${ICON_SPARK}</span><div class="text">${line}</div></div>`;
    }
    const clickable = s.expandable ? ' clickable' : '';
    let body;
    if (s.state === 'bullets' && s.bullets && s.bullets.length) {
      body = `<ul>${s.bullets.map((b) => `<li>${esc(b)}</li>`).join('')}</ul>`;
    } else {
      body = `<p>${esc(s.text || '')}${s.expandable ? '<span class="fold">More</span>' : ''}</p>`;
    }
    return `<div class="summary${clickable}" data-act="summary"><span class="spark">${ICON_SPARK}</span><div class="text">${body}</div></div>`;
  }

  /// The sender's logo when the app has one (a `data:` URL it built), else their initials.
  function avatarHTML(m) {
    const logo = state.logos[m.email];
    const inner = logo ? `<img src="${esc(logo)}" alt="">` : esc(m.initials);
    return `<span class="av${logo ? ' logo' : ''}" data-email="${esc(m.email)}">${inner}</span>`;
  }

  function lineHTML(m) {
    const draft = m.draft ? '<span class="draft">Draft</span>' : '';
    return `<div class="line" data-act="toggle">${avatarHTML(m)}` +
      `<span class="from">${esc(m.from)}</span>${draft}<span class="snip">${esc(m.snippet)}</span>` +
      `${m.draft ? draftActionsHTML('dacts') : ''}${messageMenuHTML()}<time class="date">${esc(m.date)}</time></div>`;
  }

  /// The slide-over's ··· beside each message's date: Reply, Forward and the rest for that conversation.
  function messageMenuHTML() {
    return `<span class="mmenu" data-act="message-menu" role="button" title="More" aria-label="More">${ICON_MORE}</span>`;
  }

  /// Your draft in the conversation: Edit opens it, Discard deletes it and nothing else.
  function draftActionsHTML(kind) {
    const lead = kind === 'draftnote' ? '<span>Your draft</span><span>·</span>' : '';
    return `<span class="${kind}">${lead}<span class="dact" data-act="edit-draft" role="button">Edit</span>` +
      `<span>·</span><span class="dact" data-act="discard-draft" role="button">Discard</span></span>`;
  }

  function headHTML(m) {
    const address = m.email && m.email !== m.from ? `<span class="addr">${esc(m.email)}</span>` : '';
    let details = '';
    for (const [label, value] of m.details || []) details += `<dt>${esc(label)}</dt><dd>${esc(value)}</dd>`;
    return `<div class="mhead" data-act="collapse">${avatarHTML(m)}` +
      `<div class="who"><div class="row1"><span class="name">${esc(m.from)}</span>${address}</div>` +
      `<span class="to" data-act="details">${esc(m.toLine)}${ICON_CHEVRON}</span>` +
      `<span class="to-addr" data-act="details">To: <span class="rcpt">${esc(m.toAddresses || '')}</span></span></div>` +
      `${messageMenuHTML()}<time class="date" title="${esc(m.dateFull)}">${esc(m.dateLong || m.date)}</time></div>` +
      `<dl class="details" hidden>${details}</dl>`;
  }

  function imageNoteHTML(m, body) {
    if (m.imagesOnce && m.email) {
      return `<div class="imgnote"><span>Images shown for this message</span><span>·</span>` +
        `<span class="load" data-act="always-images" role="button">Always load from ${esc(m.email)}</span></div>`;
    }
    const blocked = body && body.blocked;
    if (!blocked || m.imagesAllowed) return '';
    return `<div class="imgnote"><span>Images hidden</span><span>·</span>` +
      `<span class="load" data-act="images" role="button">Load images</span></div>`;
  }

  /// Bodies sanitized after the first paint report their blocked images only then.
  function refreshImageNote(id) {
    const element = messageElement(id);
    if (!element) return;
    const html = imageNoteHTML(state.messages.get(id), state.bodies.get(id));
    const note = element.querySelector('.imgnote');
    if (note) {
      if (note.outerHTML !== html) note.outerHTML = html;
    } else if (html) {
      element.querySelector('.mbody').insertAdjacentHTML('beforebegin', html);
    }
  }

  function attachmentsHTML(m) {
    if (!m.attachments || !m.attachments.length) return '';
    let html = '<div class="atts">';
    for (const a of m.attachments) {
      html += `<div class="att" tabindex="0" data-att="${esc(a.id)}" title="${esc(a.name)}">${a.kind === 'image' ? ICON_IMAGE : ICON_FILE}` +
        `<span class="name">${esc(a.name)}</span><span class="size">${esc(a.size)}</span></div>`;
    }
    return html + '</div>';
  }

  function messageHTML(m, open, extraClass) {
    const classes = ['msg'];
    if (open) classes.push('open');
    if (m.unread) classes.push('unread');
    if (extraClass) classes.push(extraClass);
    return `<article class="${classes.join(' ')}" data-id="${esc(m.id)}">${lineHTML(m)}${headHTML(m)}` +
      `${m.draft ? draftActionsHTML('draftnote') : ''}${imageNoteHTML(m, m.body)}<div class="mbody" data-mode="${esc(m.body ? m.body.mode : 'plain')}"></div>${attachmentsHTML(m)}</article>`;
  }

  /// Long runs of collapsed messages show the first one, a "N more" row, then the last two.
  function messagesHTML(p) {
    let html = '<section class="msgs">';
    const list = p.messages;
    let index = 0;
    while (index < list.length) {
      if (state.expanded.has(list[index].id)) {
        html += messageHTML(list[index], true);
        index += 1;
        continue;
      }
      let end = index;
      while (end < list.length && !state.expanded.has(list[end].id)) end += 1;
      const run = list.slice(index, end);
      if (run.length >= 5 && !state.showAll) {
        html += messageHTML(run[0], false);
        const hidden = run.slice(1, -2);
        html += `<div class="more" data-act="more"><span class="count">${hidden.length}</span><span>more messages</span></div>`;
        for (const m of hidden) html += messageHTML(m, false, 'hidden-run');
        for (const m of run.slice(-2)) html += messageHTML(m, false);
      } else {
        for (const m of run) html += messageHTML(m, false);
      }
      index = end;
    }
    return html + '</section>';
  }

  // MARK: Rendering

  function render(p) {
    const started = performance.now();
    const previous = state && state.key === p.key ? state : null;
    state = {
      key: p.key, payload: p, messages: new Map(), expanded: new Set(), bodies: new Map(), logos: p.logos || {},
      openQuotes: previous ? previous.openQuotes : new Set(), focus: previous ? previous.focus : -1,
      showAll: previous ? previous.showAll : false,
    };
    for (const m of p.messages) {
      state.messages.set(m.id, m);
      if (m.body) state.bodies.set(m.id, m.body);
      const wasOpen = previous && previous.messages.has(m.id) ? previous.expanded.has(m.id) : m.expanded;
      if (wasOpen) state.expanded.add(m.id);
      if (previous && !m.body && previous.bodies.has(m.id) && previous.messages.get(m.id).bodyVersion === m.bodyVersion) {
        state.bodies.set(m.id, previous.bodies.get(m.id));
      }
    }
    const scrollTop = previous ? document.scrollingElement.scrollTop : 0;
    const container = root();
    container.innerHTML = headerHTML(p) + messagesHTML(p);
    container.dataset.key = p.key;
    for (const id of state.expanded) mount(id);
    applyFocus(false);
    fitAll();
    if (previous) {
      document.scrollingElement.scrollTop = scrollTop;
    } else {
      scrollToTarget(p);
    }
    const built = performance.now() - started;
    afterPaint(() => post({ type: 'rendered', key: p.key, ms: performance.now() - started, buildMs: built }));
    return built;
  }

  function scrollToTarget(p) {
    const target = p.messages.find((m) => m.target);
    const element = target && messageElement(target.id);
    if (!element || element === root().querySelector('.msg')) { window.scrollTo(0, 0); return; }
    const top = element.getBoundingClientRect().top + window.scrollY;
    window.scrollTo(0, top > window.innerHeight * 0.4 ? top - 8 : 0);
  }

  function mount(id) {
    const element = messageElement(id);
    if (!element) return false;
    const host = element.querySelector('.mbody');
    if (host.shadowRoot) return true;
    const body = state.bodies.get(id);
    if (!body) {
      const m = state.messages.get(id);
      host.innerHTML = `<span class="pending">${esc(m.snippet || '')}</span>`;
      // A large body is being sanitized in the background and arrives through setBodies.
      if (!m.bodyLoading) post({ type: 'needBody', id });
      return false;
    }
    host.textContent = '';
    host.dataset.mode = body.mode;
    refreshImageNote(id);
    const shadow = host.attachShadow({ mode: 'open' });
    shadow.adoptedStyleSheets = [sheet()];
    if (body.css) {
      const style = document.createElement('style');
      style.textContent = body.css;
      shadow.append(style);
    }
    // `.tern-root` stands in for the mail's <html>, `.tern-body` for its <body>; mail CSS can't reach the host.
    const outer = document.createElement('div');
    outer.className = 'tern-root';
    const wrapper = document.createElement('div');
    wrapper.className = 'tern-body';
    if (body.bodyStyle) wrapper.setAttribute('style', body.bodyStyle);
    wrapper.innerHTML = body.html;
    outer.append(wrapper);
    shadow.append(outer);
    shadow.addEventListener('load', () => queueFit(), true);
    shadow.querySelectorAll('.tern-quote-toggle').forEach((toggle, index) => {
      if (state.openQuotes.has(`${id}#${index}`)) setQuote(toggle, true);
    });
    return true;
  }

  function fit(host) {
    const body = host.shadowRoot && host.shadowRoot.querySelector('.tern-body');
    if (!body) return;
    body.style.zoom = '';
    host.classList.remove('wide');
    const available = body.clientWidth;
    const needed = body.scrollWidth;
    if (available > 0 && needed > available + 2) {
      const scale = available / needed;
      body.style.zoom = String(Math.max(scale, MIN_SCALE));
      if (scale < MIN_SCALE) host.classList.add('wide');
    }
  }

  function fitAll() {
    root().querySelectorAll('.msg.open .mbody').forEach(fit);
  }

  function queueFit() {
    if (fitQueued) return;
    fitQueued = true;
    requestAnimationFrame(() => { fitQueued = false; fitAll(); });
  }

  // MARK: Messages

  function setOpen(id, open) {
    const element = messageElement(id);
    if (!element) return;
    if (open) {
      state.expanded.add(id);
      element.classList.add('open');
      element.classList.remove('hidden-run');
      mount(id);
      fit(element.querySelector('.mbody'));
    } else {
      state.expanded.delete(id);
      element.classList.remove('open', 'details-open');
    }
    post({ type: 'expanded', id, open });
  }

  function toggle(id) { setOpen(id, !state.expanded.has(id)); }

  function order() {
    return Array.from(root().querySelectorAll('.msg:not(.hidden-run)')).map((element) => element.dataset.id);
  }

  function applyFocus(scroll) {
    root().querySelectorAll('.msg.focused').forEach((element) => element.classList.remove('focused'));
    if (state.focus < 0) return;
    const ids = order();
    const element = messageElement(ids[Math.min(state.focus, ids.length - 1)]);
    if (!element) return;
    element.classList.add('focused');
    if (scroll) element.scrollIntoView({ block: 'nearest' });
  }

  function move(delta) {
    const ids = order();
    if (!ids.length) return;
    if (state.focus < 0) {
      const target = state.payload.messages.find((m) => m.target);
      const index = target ? ids.indexOf(target.id) : -1;
      state.focus = index >= 0 ? index : ids.length - 1;
    }
    state.focus = Math.min(ids.length - 1, Math.max(0, state.focus + delta));
    applyFocus(true);
  }

  function toggleFocused() {
    const ids = order();
    if (state.focus < 0) move(0);
    const id = ids[Math.min(Math.max(state.focus, 0), ids.length - 1)];
    if (id) toggle(id);
    applyFocus(true);
  }

  function setQuote(toggleElement, open) {
    const quote = toggleElement.nextElementSibling;
    if (!quote || !quote.classList.contains('tern-quote')) return;
    quote.hidden = !open;
    toggleElement.classList.toggle('open', open);
    toggleElement.setAttribute('aria-label', open ? 'Hide quoted text' : 'Show quoted text');
  }

  // MARK: Events

  function pathOf(event) {
    return event.composedPath().filter((node) => node instanceof Element);
  }

  function linkIn(path) {
    return path.find((node) => (node.localName === 'a' || node.localName === 'area') && node.hasAttribute('href'));
  }

  document.addEventListener('click', (event) => {
    if (!state) return;
    const path = pathOf(event);
    const link = linkIn(path);
    if (link) {
      event.preventDefault();
      const href = link.getAttribute('href');
      if (href.startsWith('#')) {
        const shadow = link.getRootNode();
        const name = decodeURIComponent(href.slice(1));
        if (!name) return;
        const target = shadow.getElementById ? (shadow.getElementById(name) || shadow.querySelector(`[name="${CSS.escape(name)}"]`)) : null;
        if (target) target.scrollIntoView({ block: 'start' });
        return;
      }
      post({ type: 'link', href, text: (link.textContent || '').trim().slice(0, 300) });
      return;
    }
    const quoteToggle = path.find((node) => node.classList && node.classList.contains('tern-quote-toggle'));
    if (quoteToggle) {
      const host = quoteToggle.getRootNode().host;
      const id = host && host.closest('.msg').dataset.id;
      const toggles = Array.from(quoteToggle.getRootNode().querySelectorAll('.tern-quote-toggle'));
      const key = `${id}#${toggles.indexOf(quoteToggle)}`;
      const open = !quoteToggle.classList.contains('open');
      setQuote(quoteToggle, open);
      if (open) state.openQuotes.add(key); else state.openQuotes.delete(key);
      queueFit();
      return;
    }
    const attachment = path.find((node) => node.dataset && node.dataset.att);
    if (attachment) {
      root().querySelectorAll('.att.selected').forEach((element) => element.classList.remove('selected'));
      attachment.classList.add('selected');
      attachment.focus({ preventScroll: true });
      post({ type: 'attachment', action: event.detail >= 2 ? 'open' : 'select', id: attachment.dataset.att });
      return;
    }
    const action = path.find((node) => node.dataset && node.dataset.act);
    if (!action) return;
    const message = action.closest('.msg');
    const id = message && message.dataset.id;
    switch (action.dataset.act) {
      case 'toggle':
        setOpen(id, true);
        break;
      case 'collapse': {
        const selection = window.getSelection();
        if (selection && !selection.isCollapsed) return;
        if (path.some((node) => node.dataset && node.dataset.act === 'details')) return;
        if (state.expanded.size > 1 || state.payload.messages.length > 1) setOpen(id, false);
        break;
      }
      case 'details': {
        const details = message.querySelector('.details');
        details.hidden = !details.hidden;
        message.classList.toggle('details-open', !details.hidden);
        break;
      }
      case 'more':
        state.showAll = true;
        root().querySelectorAll('.msg.hidden-run').forEach((element) => element.classList.remove('hidden-run'));
        action.remove();
        break;
      case 'images':
        post({ type: 'loadImages', id });
        break;
      case 'always-images':
        post({ type: 'alwaysImages', id, sender: state.messages.get(id).email });
        break;
      case 'summary':
        post({ type: 'summary' });
        break;
      case 'edit-draft':
        post({ type: 'editDraft', id });
        break;
      case 'tags':
      case 'message-menu': {
        // The app pops its menu up under the button, in page coordinates.
        const box = action.getBoundingClientRect();
        post({ type: action.dataset.act === 'tags' ? 'tagMenu' : 'messageMenu', id, x: box.left, y: box.bottom + 4 });
        break;
      }
      case 'discard-draft':
        post({ type: 'discardDraft', id });
        break;
    }
  });

  document.addEventListener('dblclick', (event) => {
    const attachment = pathOf(event).find((node) => node.dataset && node.dataset.att);
    if (attachment) event.preventDefault();
  });

  document.addEventListener('contextmenu', (event) => {
    const attachment = pathOf(event).find((node) => node.dataset && node.dataset.att);
    if (!attachment) return;
    event.preventDefault();
    attachment.classList.add('selected');
    post({ type: 'attachment', action: 'menu', id: attachment.dataset.att, x: event.clientX, y: event.clientY });
  });

  document.addEventListener('mouseover', (event) => {
    const link = linkIn(pathOf(event));
    const href = link ? link.getAttribute('href') : null;
    if (href === hoverHref) return;
    hoverHref = href;
    post({ type: 'hover', href, text: link ? (link.textContent || '').trim().slice(0, 300) : null });
  });

  document.addEventListener('mouseleave', () => {
    if (hoverHref !== null) { hoverHref = null; post({ type: 'hover', href: null }); }
  });

  // The keys of Next and Previous Message, Open and Quick Look as the user has them, by event.key name
  // ("n", "Enter", "Shift+Tab"); the app sends them with Tern.setKeys.
  let keys = {};

  document.addEventListener('keydown', (event) => {
    if (!state || event.metaKey || event.ctrlKey || event.altKey) return;
    const active = pathOf(event)[0];
    if (active && (active.isContentEditable || /^(input|textarea|select)$/i.test(active.localName))) return;
    const attachment = active && active.dataset && active.dataset.att ? active : null;
    if (event.key === 'Enter' && active && linkIn([active])) return;
    switch (keys[(event.shiftKey && !/^[^ ]$/.test(event.key) ? 'Shift+' : '') + event.key]) {
      case 'next': move(1); break;
      case 'previous': move(-1); break;
      case 'open':
        if (attachment) { post({ type: 'attachment', action: 'open', id: attachment.dataset.att }); break; }
        if (active && active.classList && active.classList.contains('tern-quote-toggle')) { active.click(); break; }
        toggleFocused();
        break;
      case 'quicklook':
        if (!attachment) return;
        post({ type: 'attachment', action: 'quicklook', id: attachment.dataset.att });
        break;
      default:
        return;
    }
    event.preventDefault();
    event.stopPropagation();
  }, true);

  new ResizeObserver(() => queueFit()).observe(document.getElementById('thread'));

  // MARK: API for the app

  window.Tern = {
    render,
    /// Header-only refresh (chips, summary) without touching message state.
    updateHeader(p) {
      if (!state || state.key !== p.key) return;
      state.payload.chips = p.chips;
      state.payload.summary = p.summary;
      const head = root().querySelector('.head');
      if (head) head.outerHTML = headerHTML(state.payload);
    },
    setSummary(key, summary) {
      if (!state || state.key !== key) return;
      state.payload.summary = summary;
      const element = root().querySelector('.summary');
      if (element) element.outerHTML = summaryHTML(summary);
    },
    /// Bodies sanitized after the first paint (collapsed messages), or on demand.
    setBodies(key, bodies) {
      if (!state || state.key !== key) return;
      for (const [id, body] of Object.entries(bodies)) {
        state.bodies.set(id, body);
        if (state.expanded.has(id)) {
          const host = messageElement(id).querySelector('.mbody');
          if (!host.shadowRoot && mount(id)) fit(host);
        }
      }
    },
    /// Sender logos that arrived after the paint: swaps only the matching avatars, so scroll position,
    /// open messages and focus stay as they are.
    setLogos(key, logos) {
      if (!state || state.key !== key) return;
      for (const [email, logo] of Object.entries(logos)) {
        if (state.logos[email] === logo) continue;
        state.logos[email] = logo;
        root().querySelectorAll(`.av[data-email="${CSS.escape(email)}"]`).forEach((element) => {
          element.classList.add('logo');
          element.innerHTML = `<img src="${esc(logo)}" alt="">`;
        });
      }
    },
    /// A remote image that couldn't load: it keeps the box its mail declared and shows nothing, and one that
    /// declared no height folds away instead of standing at a guessed size. A copy of the same image that already
    /// arrived stays as it is.
    imageFailed(url) {
      for (const host of root().querySelectorAll('.mbody')) {
        if (!host.shadowRoot) continue;
        for (const image of host.shadowRoot.querySelectorAll('img[src]')) {
          if (image.getAttribute('src') !== url || (image.complete && image.naturalWidth > 0)) continue;
          image.setAttribute('data-tern-failed', '');
        }
      }
    },
    setTheme(theme) { document.documentElement.dataset.theme = theme; },
    /// "panel" in the slide-over, "column" elsewhere.
    setLayout(layout) { document.documentElement.dataset.layout = layout; queueFit(); },
    setKeys(map) { keys = map || {}; },
    next() { move(1); },
    previous() { move(-1); },
    toggleFocused,
    expandAll() {
      if (!state) return;
      state.showAll = true;
      root().querySelectorAll('.msg.hidden-run').forEach((element) => element.classList.remove('hidden-run'));
      const more = root().querySelector('.more');
      if (more) more.remove();
      for (const id of state.messages.keys()) if (!state.expanded.has(id)) setOpen(id, true);
    },
    selectedAttachment() {
      const element = root().querySelector('.att.selected') || (document.activeElement && document.activeElement.dataset && document.activeElement.dataset.att ? document.activeElement : null);
      return element ? element.dataset.att : null;
    },
    setAttachmentBusy(id, busy) {
      const element = root().querySelector(`.att[data-att="${CSS.escape(id)}"]`);
      if (element) element.classList.toggle('busy', busy);
    },
    clear() { state = null; root().innerHTML = ''; window.scrollTo(0, 0); },
    fontsReady() {
      return Promise.all(['400 13px Inter', '500 13px Inter', '600 13px Inter', '600 24px "Inter Display"']
        .map((font) => document.fonts.load(font))).then(() => true);
    },
  };

  sheet();
  post({ type: 'boot' });
})();
